DELETE FROM sqlite_sequence;
INSERT INTO sqlite_sequence VALUES('jobs',69);
CREATE TRIGGER `insert_jobs_state` BEFORE INSERT ON `jobs`
BEGIN
    SELECT CASE 
    WHEN NEW.`state` IN ('submitted', 'processing')
        AND (
            SELECT COUNT(*) 
            FROM `jobs` 
            WHERE `ns_url` = NEW.`ns_url`
            AND `state` IN ('submitted', 'processing')
        ) > 0
    THEN
        RAISE(ABORT, 'Job already queued')
    END;
END;
CREATE TRIGGER `update_jobs_state` BEFORE INSERT ON `jobs`
BEGIN
    SELECT CASE 
    WHEN NEW.`state` IN ('submitted', 'processing')
        AND (
            SELECT COUNT(*) 
            FROM `jobs` 
            WHERE `ns_url` = NEW.`ns_url`
            AND `state` IN ('submitted', 'processing')
        ) > 0
    THEN
        RAISE(ABORT, 'Job already queued')
    END;
END;
COMMIT;
